;	###################################################################
;	s.asm - Edited 1/30/2026 to convert syntax for as1600 assembler
;	###################################################################
;
;	6/10/86 -- xx modified
;	6/12/86 -- nuvatek modified
;
;	Contributed by Steve Ettinger to the Intellivision Overlay Editor
;	project as reference material for the SFX Lab. Used to translate
;	example bytecode sequences into the editor's flat SOUND-register
;	output format. The macros themselves emit DECLE words for a runtime
;	interpreter (engine source is not included here).
;

;
;	INFORMATION ABOUT SOUND CHIP
;

SCHIP		EQU	$1F0	;FIRST ADR IN SOUND CHIP
SC_F0	EQU	0		;FINE TUNE CHANNEL 0
SC_F1	EQU	1		;FINE TUNE CHANNEL 1
SC_F2	EQU 2		;FINE TUNE CHANNEL 2
SC_FE	EQU 3		;FINE TUNE ENVELOPE

SC_C0	EQU	4		;COARSE TUNE CHANNEL 0
SC_C1	EQU	5		;COARSE TUNE CHANNEL 1
SC_C2	EQU	6		;COARSE TUNE CHANNEL 2
SC_CE	EQU	7		;COARSE TUNE ENVELOPE
;SC_ENBL	EQU	&10	;ENABLE SOUND
SC_ENBL	EQU	$8	;ENABLE SOUND
					;0=ON, 1=OFFSC_ENBL	EQU	&10	;ENABLE SOUND
;NONE	EQU	&77
NONE	EQU	77Q
;NONE	EQU	%111111
				;NOISE ON CHANNEL 0,1,2 = BITS 3,4,5
;NCH1	EQU	&67
;NCH2	EQU	&57
;NCH3	EQU	&37
NCH1	EQU	%110111
NCH2	EQU	%101111
NCH3	EQU	%011111					;TONE ON CHANNEL 0,1,2 = BITS 0,1,2

;TCH1	EQU	&76
;TCH2	EQU	&75
;TCH3	EQU	&73
TCH1	EQU	%111110
TCH2	EQU	%111101
TCH3	EQU	%111011
					;ALWAYS CLEAR BITS 6,7 (FOR KEYPAD)
;SC_FN	EQU	&11		;FREQUENCY OF NOISE GENERATOR
;SC_ENVC	EQU	&12		;ENVELOPE CONTROL
SC_FN	EQU	%001001		;FREQUENCY OF NOISE GENERATOR
SC_ENVC	EQU	%001010		;ENVELOPE CONTROL
HOLD	EQU	$01		;HOLD POSITION OF ENVELOPE
ALTERNATE	EQU	$02	;ALTERNATING EVELOPE
ATTACK	EQU	$04		;ENVELOPE RISE
DECAY	EQU	$00		;ENVELOPE FALL
CONTINUE	EQU	$08	;CONTINUOUS ENVELOPE
;SC_VOL0	EQU	&13		;VOLUME CHANNEL 0
;SC_VOL1	EQU	&14		;VOLUME CHANNEL 1
;SC_VOL2	EQU	&15		;VOLUME CHANNEL 2
SC_VOL0	EQU	%001011		;VOLUME CHANNEL 0
SC_VOL1	EQU	%001100		;VOLUME CHANNEL 1
SC_VOL2	EQU	%001101		;VOLUME CHANNEL 2
					;BITS 4,5 HI WILL USE ENVELOPE, ELSE JUST VOL

;BTNADR	EQU	SCHIP+&16	;ADR OF BUTTON PORT
BTNADR	EQU	SCHIP+$E	;ADR OF BUTTON PORT

;
;	NOTES
;

MACRO	N	(TONE,OCTAVE,LENGTH,PAUSE)
;N	MACRO	TONE,OCTAVE,LENGTH,PAUSE

LENGTH__	SET	%LENGTH%-1

	IF (LENGTH__ - 8) AND $8000	;IF LENGTH IS GREATER THAN 8
	  DECLE	$3F0 OR (((LENGTH__/2) AND 4) OR ((LENGTH__/8) AND 2) OR ((LENGTH__/32) AND 1))
	ENDI

	DECLE	((%TONE% +(%OCTAVE%-1)*12)*16) OR (%PAUSE%*8) OR (((LENGTH__*4) AND 4) OR (LENGTH__ AND 2) OR ((LENGTH__/4) AND 1))
ENDM

MACRO	P	(LENGTH)

;P	MACRO	LENGTH
	N	0,1,%LENGTH%,1
ENDM

C	EQU 0	;C
CS	EQU 1	;C SHARP
DF	EQU 1	;D FLAT
D	EQU 2	;D
;	DS	EQU 3	;D SHARP -- also define storage pseudo-op
EF	EQU 3	;E FLAT
E	EQU 4	;E
F	EQU 5	;F
FS	EQU 6	;F SHARP
GF	EQU 6	;G FLAT
G	EQU 7	;G
GS	EQU 8	;G SHARP
AF	EQU 8	;A FLAT
A	EQU 9	;A
AS	EQU	10	;A SHARP
BF	EQU	10	;B FLAT
B	EQU	11	;B

;
;	SOUND EFFECTS
;

CH1	EQU	%00
CH2	EQU	%10
CH3	EQU	%01
ALL	EQU	%11
SR1	EQU	%00
SR2	EQU	%10
SR3	EQU	%01
SR4	EQU	%11
ONS	EQU	1
OFFS	EQU	0
YRET	EQU	0	;RETURN FOLLOWING FIN OPCODE
NRET	EQU	1	;DON'T RETURN
USEENV	EQU	1	;VOLUME CODE TO USE ENVELOPE

;FREQ	MACRO	CHANNEL,FREQUENCY,VOLUME
MACRO	FREQ	(CHANNEL,FREQUENCY,VOLUME)
	DECLE	(%VOLUME%)*64 OR ((%FREQUENCY%) AND $C00)/64 OR (%CHANNEL%)*4 OR %00
	DECLE	(%FREQUENCY%) AND $3FF
ENDM

;EFREQ	MACRO	FREQUENCY
MACRO	EFREQ	(FREQUENCY)
	DECLE	((%FREQUENCY%) AND $FC00)/64 OR $C
	DECLE	(%FREQUENCY%) AND $3FF
ENDM

;FREQV	MACRO	CHANNEL,VELOCITY,WAVER
MACRO	FREQV	(CHANNEL,VELOCITY,WAVER)
	DECLE	(%WAVER%)*16 OR %0001
	DECLE	(%VELOCITY%)*4 OR %CHANNEL%
ENDM

;ENABLE	MACRO	VALUE
MACRO	ENABLE	(VALUE)
	DECLE	(%VALUE%)*16 OR %1001
ENDM

;NFREQ	MACRO	FREQUENCY
MACRO	NFREQ	(FREQUENCY)
	DECLE	(%FREQUENCY%)*32 OR %01101
ENDM

;NFREQV	MACRO	VELOCITY
MACRO	NFREQV	(VELOCITY)
	DECLE	%00001111, %VELOCITY%
ENDM

;ECHAR	MACRO	BITS
MACRO	ECHAR	(BITS)
	DECLE	(%BITS%)*64 OR %001011
ENDM

;VOL	MACRO	CHANNEL,VOLUME
MACRO	VOL	(CHANNEL,VOLUME)
	DECLE	(%VOLUME%)*64 OR (%CHANNEL%)*16 OR %0101
ENDM

;VOLV	MACRO	CHANNEL,VELOCITY
MACRO	VOLV	(CHANNEL,VELOCITY)
	DECLE	(%VELOCITY%)*16 OR (%CHANNEL%)*4 OR %10
ENDM

;EUSE	MACRO	CHAN0,CHAN1,CHAN2
MACRO	EUSE	(CHAN0,CHAN1,CHAN2)
	DECLE	(%CHAN0% OR ((%CHAN1%)*2) OR ((%CHAN2%)*4))*128 OR %0110111
ENDM

;PAUSE	MACRO	TICKS
MACRO	PAUSE	(TICKS)
	IF ((%TICKS%)-17) AND $8000
	  DECLE	%10001111,(%TICKS%)-1
	ELSE
	  DECLE	((%TICKS%)-1)*64 OR %101011
	ENDI
ENDM

;SETR	MACRO	REGISTER,VALUE
MACRO	SETR	(REGISTER,VALUE)
	IF ((%VALUE%)-8) AND $8000
	  DECLE	((%REGISTER%) AND 1)*512 OR ((%REGISTER%) AND 2)*128 OR %01001111, %VALUE%
	ELSE
	  DECLE	(%VALUE%)*128 OR (%REGISTER%)*32 OR %11101
	ENDI
ENDM

;PDJNZ	MACRO	TICKS,REGISTER,LABEL
MACRO	PDJNZ	(TICKS,REGISTER,LABEL)

pdjnz_label.%%	EQU	$
;	DECLE	(TICKS)*32 | %00011, (LABEL-(pdxxx+2))*4 | REGISTER
	DECLE	(%TICKS%) * 32 OR %00011, (%LABEL%-(pdjnz_label.%%+2))*4 OR %REGISTER%
ENDM

;FIN	MACRO	SOUNDS,RETTYPE
MACRO	FIN	(SOUNDS,RETTYPE)
	DECLE	(%RETTYPE%)*512 OR (%SOUNDS%)*256 OR %11001111
ENDM

;NOOP	MACRO
MACRO	NOOP

ENDM

;RFREQ	MACRO	ADJUSTMENT
MACRO	RFREQ	(ADJUSTMENT)
	DECLE	((%ADJUSTMENT%)-1)*64 OR %011011
ENDM

;RFREQV	MACRO	ADJUSTMENT
MACRO	RFREQV	(ADJUSTMENT)
	DECLE	((%ADJUSTMENT%)-1)*64 OR %111011
ENDM

;RNFREQ	MACRO	ADJUSTMENT
MACRO	RNFREQ	(ADJUSTMENT)
	DECLE	((%ADJUSTMENT%)-1)*64 OR %000111
ENDM

;RNFREQV	MACRO	ADJUSTMENT
MACRO	RNFREQV	(ADJUSTMENT)
	DECLE	((%ADJUSTMENT%)-1)*64 OR %100111
ENDM

;STUNIT	MACRO	QUNIT
MACRO	STUNIT	(QUNIT)
	DECLE	((%QUNIT%)-1)*256 OR %00101111
ENDM

;UCALL	MACRO	ADDRESS
MACRO	UCALL	(ADDRESS)
	DECLE	%1110111
	BIDECLE	%ADDRESS%
ENDM

;RPAUSE	MACRO	MINTIME,MAXTIME
MACRO	RPAUSE	(MINTIME,MAXTIME)

RPAUSE_DIFF SET	(%MAXTIME%)-(%MINTIME%)
	DECLE	(RPAUSE_DIFF AND $78)*8 OR %010111
	DECLE	(%MINTIME%)*8 OR (RPAUSE_DIFF AND 4)/4 OR (RPAUSE_DIFF AND 2) OR (RPAUSE_DIFF AND 1)*4
ENDM

;RSETR	MACRO	REGISTER,MINVAL,MAXVAL
MACRO	RSETR	(REGISTER,MINVAL,MAXVAL)

RSETR_DIFF SET (%MAXVAL%)-(%MINVAL%)
	DECLE	(RSETR_DIFF AND $7C)*8 OR %10011
	DECLE	(%MINVAL%)*16 OR (RSETR_DIFF AND 2)*2 OR (RSETR_DIFF AND 1)*8 OR %REGISTER%
ENDM
